/**
 * GH#571 (prog #649) cumulative bond coupon: tranche layout v2 (176 B), decoder validity, the coupon rules and the
 * tag 108 / 110 / 78 quotes, all against the REAL wrapper crate at prog f7a54350 / engine 2f05df8c.
 *
 * Fixture: test/fixtures/bond-carry-571-parity.json, generated by scripts/bond-carry-parity/sdk_571_parity.rs (see its
 * header): records written by the program's own `init_bond_tranche` / `write_bond_tranche` with the program reader's
 * verdict, rules from the real `bond_v20` functions and `BondTrancheV20::claim_upper_bound_at`, and scenarios = the
 * handler bodies transcribed onto those functions, with the program-written tranche bytes after every step.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as M from "../src/abi/v22-math.js";
import * as S from "../src/abi/v22-state.js";
import { ACCOUNT_KIND, LAYOUT_V22, UnknownLayoutError } from "../src/abi/layout.js";

interface Rule { fn: string; in: string[]; out: (string | null)[] }
interface Step {
  op: string; now: string; drawn: string; v: string; vWorse: string; cEff: string; drawOut: string; backstop: string; p1: string; p2: string;
  ok: boolean; code?: number; shares?: string; settled?: string | null; claimAtPrice?: string | null; atoms?: string; claimAfter?: string;
  coupon?: string; rest?: string; accrued?: string; openNow?: boolean; open?: boolean; after: string; afterReads: boolean;
}
const FX = JSON.parse(readFileSync(new URL("./fixtures/bond-carry-571-parity.json", import.meta.url), "utf8")) as {
  prog: string; engine: string;
  layout: { body: number; accountLen: number; version: number; kind: number; couponDenom: string; off: Record<string, number> };
  records: Record<string, { hex: string; programReads: boolean }>;
  rules: Rule[];
  scenarios: { name: string; start: string; steps: Step[] }[];
};
const unhex = (s: string) => Uint8Array.from(Buffer.from(s, "hex"));
const B = (s: string) => BigInt(s);
const N = (x: bigint | null | undefined) => (x === null || x === undefined ? null : x.toString());
const COUPON_KEYS = ["cBAtoms", "bSharesTotal", "couponArrearsAtoms", "couponUnfundedAtoms", "couponAccrualRem", "couponGateSeen", "lastCouponSlot"] as const;
const pick = (t: M.BondCouponStateV22, extra: readonly (keyof S.BondTrancheV20)[] = []) => {
  const o: Record<string, unknown> = {};
  for (const k of COUPON_KEYS) o[k] = t[k];
  for (const k of extra) o[k] = (t as unknown as Record<string, unknown>)[k];
  return o;
};

describe("GH#571 pinned oracle", () => {
  it("prog #649 head f7a54350, engine 2f05df8c", () => {
    expect(FX.prog).toBe("f7a54350bd17d51d45effa0cb9df66d7eb8e69cf");
    expect(FX.engine).toBe("2f05df8c8c1edd85734120e1322420621fc33cf0");
  });
});

describe("BondTrancheV20 v2 layout == rustc", () => {
  it("176 B body, version 2, kind 11, every offset, COUPON_DENOM", () => {
    expect(LAYOUT_V22.accounts.bondTrancheBody).toBe(FX.layout.body);
    expect(FX.layout.body).toBe(176);
    expect(LAYOUT_V22.accounts.headerLen + LAYOUT_V22.accounts.bondTrancheBody).toBe(FX.layout.accountLen);
    expect(S.BOND_TRANCHE_VERSION_V22).toBe(FX.layout.version);
    expect(ACCOUNT_KIND.BondTranche).toBe(FX.layout.kind);
    expect(M.COUPON_DENOM_V22.toString()).toBe(FX.layout.couponDenom);
    expect(S.BOND_COUPON_DENOM_V22).toBe(M.COUPON_DENOM_V22);
    const { marketGroup, ...off } = S.BOND_TRANCHE_FIELD_OFF_V22;
    expect(marketGroup).toBe(0);
    expect(off).toEqual(FX.layout.off);
  });
});

describe("decodeBondTrancheV20 accepts exactly what the program reads", () => {
  it("every record: decoded iff read_bond_tranche accepts", () => {
    expect(Object.keys(FX.records).length).toBeGreaterThanOrEqual(11);
    for (const [name, r] of Object.entries(FX.records)) {
      const run = () => S.decodeBondTrancheV20(unhex(r.hex));
      if (r.programReads) expect(run, name).not.toThrow();
      else expect(run, name).toThrow(UnknownLayoutError);
    }
  });
  it("v1 (128 B) and the intermediate 144 B form are refused as too short; version 1 at full length as invalid", () => {
    for (const n of ["truncated128", "truncated144"]) {
      expect(FX.records[n].programReads).toBe(false);
      expect(() => S.decodeBondTrancheV20(unhex(FX.records[n].hex))).toThrow(/too short/);
    }
    expect(FX.records.v1Version.programReads).toBe(false);
    expect(() => S.decodeBondTrancheV20(unhex(FX.records.v1Version.hex))).toThrow(/validate_bond_tranche/);
  });
  it("the full record round-trips every v2 field", () => {
    const t = S.decodeBondTrancheV20(unhex(FX.records.full.hex));
    expect(t).toMatchObject({
      cBAtoms: 1_000_000_000_000_000_000_123n, bSharesTotal: 999_999_999_999_999_999_999n, principalInLpAtoms: 5n, bondDrawnOutstandingAtoms: 6n,
      lastCouponSlot: 777n, couponBpsPerYear: 801, couponUtilBonusBps: 0, bondCooldownSlots: 9_001, bondCapBpsOfC: 4_999, version: 2, bump: 250,
      lastUtilBps: 1234, couponPaidTotalAtoms: 4242n, couponArrearsAtoms: 0x0123_4567_89ab_cdef_1122_3344n, couponUnfundedAtoms: 0x0eed_dccb_baa9_9887n,
      couponAccrualRem: M.COUPON_DENOM_V22 - 1n, couponGateSeen: (1n << 63n) | 0x0102_0304_0506_0708n,
    });
    // the receivable outlives the last bond: K == B == 0 with R > 0 is a valid record
    expect(S.decodeBondTrancheV20(unhex(FX.records.receivableOnEmpty.hex)).couponArrearsAtoms).toBe(77n);
  });
});

describe("coupon rules == the crate", () => {
  const bool = (s: string) => s === "true";
  const fns: Record<string, (i: string[]) => (string | null)[]> = {
    settle: (i) => {
      const r = M.couponSettleV22(B(i[0]), B(i[1]), B(i[2]), Number(i[3]), B(i[4]), bool(i[5]), B(i[6]));
      return r === null ? [] : r.map(String);
    },
    cap: (i) => [N(M.couponArrearsCapV22(B(i[0]), Number(i[1])))],
    funded: (i) => [String(M.bondFundedClaimV22(B(i[0]), B(i[1])))],
    gateSeen: (i) => [String(M.couponGateSeenV22(B(i[0]), bool(i[1])))],
    intervalClean: (i) => [String(M.couponIntervalCleanV22(B(i[0]), B(i[1])))],
    payFromLeg: (i) => M.couponPayFromLegV22(B(i[0]), B(i[1])).map(String),
    meterDeposit: (i) => [N(M.couponMeterAfterDepositV22(B(i[0]), B(i[1]), B(i[2])))],
    meterRedeem: (i) => [N(M.couponMeterAfterRedemptionV22(B(i[0]), B(i[1]), B(i[2])))],
    payOpen: (i) => [String(M.couponPayOpenV22(bool(i[0]), bool(i[1]), B(i[2]), B(i[3])))],
    upperBound: (i) => {
      const t = { cBAtoms: B(i[0]), bSharesTotal: B(i[0]), couponUnfundedAtoms: B(i[1]), couponAccrualRem: B(i[2]), lastCouponSlot: B(i[3]), couponBpsPerYear: Number(i[4]), couponUtilBonusBps: 0, couponArrearsAtoms: 0n, couponGateSeen: 0n };
      return [N(M.bondClaimUpperBoundAtV22(t, B(i[5])))];
    },
  };
  it("every row", () => {
    const seen = new Set<string>();
    expect(FX.rules.length).toBeGreaterThan(1_000);
    for (const r of FX.rules) {
      seen.add(r.fn);
      expect(fns[r.fn], `no SDK mapping for ${r.fn}`).toBeDefined();
      const want = r.fn === "settle" && r.out.length === 1 && r.out[0] === null ? [] : r.out;
      expect(fns[r.fn](r.in), `${r.fn}(${r.in.join(",")})`).toEqual(want);
    }
    expect([...seen].sort()).toEqual(Object.keys(fns).sort());
    // the grid reaches the cap, the overflow (None) and the closed gate
    expect(FX.rules.some((r) => r.fn === "settle" && r.out.length === 1 && r.out[0] === null)).toBe(true);
    expect(FX.rules.some((r) => r.fn === "settle" && r.in[5] === "false" && r.out[0] === "0" && r.out[1] === r.in[2])).toBe(true);
  });
  it("NEGATIVE CONTROL: the pre-#571 coupon (no remainder, no cap) disagrees with the crate", () => {
    const rows = FX.rules.filter((r) => r.fn === "settle" && r.out.length === 2 && r.in[5] === "true" && r.in[2] !== "0");
    expect(rows.length).toBeGreaterThan(10);
    const old = (i: string[]) => [N(M.couponDueV22(M.couponBaseV22(B(i[0]), B(i[6])), Number(i[3]), B(i[4]))), "0"];
    expect(rows.some((r) => JSON.stringify(old(r.in)) !== JSON.stringify(r.out))).toBe(true);
  });
});

/** Replay one scenario through the SDK, chaining the SDK's own tranche, and compare with the program bytes. */
function replay(sc: { name: string; start: string; steps: Step[] }, quoteDeposit = M.quoteBondDepositV22): number {
  let t: S.BondTrancheV20 = S.decodeBondTrancheV20(unhex(sc.start));
  let checked = 0;
  for (const [n, s] of sc.steps.entries()) {
    const where = `${sc.name} step ${n} ${s.op}`;
    expect(s.afterReads, where).toBe(true);
    const after = S.decodeBondTrancheV20(unhex(s.after));
    const env = { nowSlot: B(s.now), seniorDrawnAtoms: B(s.drawn), seniorClaimEff: B(s.cEff), seniorDrawOutstandingAtoms: B(s.drawOut), backstopOutstandingAtoms: B(s.backstop) };
    if (s.op === "deposit") {
      const q = quoteDeposit({ amount: B(s.p1), tranche: t, vaultValue: B(s.vWorse), ...env });
      expect([q.refusal?.code ?? null, N(q.settledCoupon), N(q.claimAtPrice)], where).toEqual([s.ok ? null : s.code, s.settled ?? null, s.claimAtPrice ?? null]);
      if (s.ok) {
        expect(N(q.shares), where).toBe(s.shares);
        t = q.trancheAfter!;
      }
    } else if (s.op.startsWith("withdraw")) {
      const live = s.op === "withdrawResolved" ? undefined : s.op === "withdrawLiveLocked"
        ? { nCapAfter: 0n, oiLongQ: 1n, oiShortQ: 0n, lpEffAbsQ: 0n }
        : { nCapAfter: null, oiLongQ: 0n, oiShortQ: 0n, lpEffAbsQ: 0n };
      const q = M.quoteBondWithdrawV22({ shares: B(s.p1), tranche: t, vaultValue: B(s.vWorse), live, ...env });
      expect([q.refusal?.code ?? null, N(q.settledCoupon)], where).toEqual([s.ok ? null : s.code, s.settled ?? null]);
      if (s.ok) {
        expect([N(q.atoms), N(q.claimAfter)], where).toEqual([s.atoms, s.claimAfter]);
        t = q.trancheAfter!;
      }
    } else {
      const r = M.bondCouponTakeV22({ tranche: t, available: B(s.p1), live: s.op === "crank", seniorDrawOutstandingAtoms: B(s.drawOut), seniorDrawnAtoms: B(s.drawn), bondValueBeforeLeg: B(s.p2), nowSlot: B(s.now) });
      expect(r, where).not.toBeNull();
      expect([N(r!.coupon), N(r!.rest), N(r!.accrued), r!.openNow, r!.open], where).toEqual([s.coupon, s.rest, s.accrued, s.openNow, s.open]);
      t = r!.tranche;
      expect(pick(t, ["lastUtilBps", "couponPaidTotalAtoms"]), where).toEqual(pick(after, ["lastUtilBps", "couponPaidTotalAtoms"]));
    }
    expect(pick(t), where).toEqual(pick(after));
    checked++;
  }
  return checked;
}

describe("tag 108 / 110 / 78 quotes == the program's handler sequence (state bytes after every step)", () => {
  it("every scenario, every step", () => {
    expect(FX.scenarios.map((s) => s.name)).toEqual([
      "newcomer_neutral_8pct", "crank_every_slot_carries_remainder", "gate_memory_and_impairment",
      "cap_meter_full_exit_receivable_outlives", "empty_tranche_pays_receivable",
    ]);
    let n = 0;
    for (const sc of FX.scenarios) n += replay(sc);
    expect(n).toBe(FX.scenarios.reduce((a, s) => a + s.steps.length, 0));
  });
  it("the scenarios exercise every refusal and the coupon paths they claim to", () => {
    const steps = FX.scenarios.flatMap((s) => s.steps);
    expect(new Set(steps.filter((s) => !s.ok).map((s) => s.code))).toEqual(new Set([89, 107, 108, 109, 123, 124]));
    expect(steps.some((s) => s.op === "crank" && s.openNow && !s.open && B(s.coupon!) > 0n)).toBe(true); // F2: forfeit, still pays
    expect(steps.some((s) => s.op === "crank" && !s.openNow && B(s.coupon!) > 0n)).toBe(true); // empty tranche pays R
    expect(steps.some((s) => s.op === "deposit" && s.ok && B(s.settled!) > 0n)).toBe(true);
  });
  it("NEGATIVE CONTROL: pricing at the unsettled K (the pre-#571 quote) mints more shares than the program", () => {
    const stale: typeof M.quoteBondDepositV22 = (i) => M.quoteBondDepositV22({ ...i, nowSlot: i.tranche.lastCouponSlot });
    const sc = FX.scenarios.find((s) => s.name === "newcomer_neutral_8pct")!;
    expect(() => replay(sc, stale)).toThrow();
  });
});
